{"query":"
query($owner: String!, $repo: String!, $number: Int!, $before: String) {
  repository(owner: $owner, name: $repo) {
    issue(number: $number) {
      number state stateReason closedAt url
      timelineItems(last: 100, before: $before, itemTypes: [CLOSED_EVENT, REOPENED_EVENT, CROSS_REFERENCED_EVENT, CONNECTED_EVENT, MARKED_AS_DUPLICATE_EVENT]) {
        pageInfo { hasPreviousPage startCursor }
        nodes {
          __typename
          ... on ClosedEvent { createdAt closer { __typename ... on PullRequest { number title url merged mergedAt baseRefName mergeCommit { oid } repository { nameWithOwner } } ... on Commit { oid url repository { nameWithOwner } } } }
          ... on ReopenedEvent { createdAt }
          ... on CrossReferencedEvent { createdAt willCloseTarget source { __typename ... on PullRequest { number title url merged mergedAt baseRefName mergeCommit { oid } repository { nameWithOwner } } } }
          ... on ConnectedEvent { createdAt subject { __typename ... on PullRequest { number title url merged mergedAt baseRefName mergeCommit { oid } repository { nameWithOwner } } } }
          ... on MarkedAsDuplicateEvent { createdAt canonical { __typename ... on Issue { number repository { nameWithOwner } } } }
        }
      }
    }
  }
}","variables":{"owner":"axios","repo":"axios","number":5011,"before":null}}
